export function tokenisationWeekendSvg(lang, kind, mobile = false) {
 if (typeof lang !== 'string' || !['fr','en'].includes(lang) || typeof kind !== 'string' || !TOKENISATION_WEEKEND_KINDS.includes(kind) || typeof mobile !== 'boolean') throw new TypeError('Invalid tokenisation weekend figure variant');
 return FIGURES[`${kind}-${lang}-${mobile ? 'mobile' : 'desktop'}`];
}
